Code.Terraform:
```hcl
resource "aws_bedrockagentcore_gateway" "example_resource" {
  name            = "example_resource"
  role_arn        = aws_iam_role.example_resource.arn
  authorizer_type = "CUSTOM_JWT"

  authorizer_configuration {
    custom_jwt_authorizer {
      discovery_url = "https://example.com/.well-known/openid-configuration"
      # Critical: without allowed_clients or allowed_audience any token the
      # issuer signs is accepted, including tokens minted for other apps
      allowed_clients = ["example-client-id"]
    }
  }
}
